<?php
require_once __DIR__.'/../config/bootstrap.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'add');if($action==='toggle'){db()->prepare('UPDATE navigation_menus SET is_active=1-is_active WHERE id=?')->execute([(int)($_POST['id']??0)]);header('Location: /admin/navigation.php');exit;}if($action==='delete'){db()->prepare('DELETE FROM navigation_menus WHERE id=?')->execute([(int)($_POST['id']??0)]);header('Location: /admin/navigation.php');exit;}$label=trim((string)($_POST['label']??''));$url=trim((string)($_POST['link_value']??''));if($url!=='' && !(str_starts_with($url,'/') && !str_starts_with($url,'//')) && !preg_match('#^https://#i',$url)){http_response_code(422);exit('Menu destinations must be local paths or HTTPS URLs.');}$parent=(int)($_POST['parent_id']??0);if($label&&$url){$s=db()->prepare("INSERT INTO navigation_menus(menu_location,label,link_type,link_value,parent_id,sort_order,is_active) VALUES('header',?,'custom',?,?,?,1)");$s->execute([$label,$url,$parent?:null,(int)($_POST['sort_order']??0)]);}header('Location: /admin/navigation.php');exit;}$rows=db()->query('SELECT n.*,p.label parent_label FROM navigation_menus n LEFT JOIN navigation_menus p ON p.id=n.parent_id ORDER BY n.parent_id,n.sort_order,n.id')->fetchAll();$pageTitle='Navigation — Ikki';require __DIR__.'/../includes/header.php';?><div class="admin-shell"><h1 class="page-title">Navigation manager</h1><nav class="admin-nav"><a href="/admin/">Dashboard</a><a href="/admin/pages.php">Pages</a><a href="/admin/navigation.php">Navigation</a></nav><form method="post" class="site-form"><?=csrf_field()?><div class="form-grid"><div><label class="field-label">Menu label</label><input class="field" name="label" required></div><div><label class="field-label">URL or path</label><input class="field" name="link_value" placeholder="/shop.php" required></div><div><label class="field-label">Parent menu (optional)</label><select name="parent_id"><option value="0">Top-level item</option><?php foreach($rows as $r):if(!$r['parent_id']):?><option value="<?=(int)$r['id']?>"><?=e($r['label'])?></option><?php endif;endforeach;?></select></div><div><label class="field-label">Sort order</label><input class="field" name="sort_order" type="number" value="0"></div></div><p><button class="btn">Add menu item</button></p></form><table class="cart-table"><thead><tr><th>Menu item</th><th>Parent</th><th>Destination</th><th>Visibility</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['label'])?></td><td><?=e($r['parent_label']??'—')?></td><td><?=e($r['link_value'])?></td><td><?=(int)$r['is_active']?'Active':'Hidden'?></td><td><form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn btn-outline" type="submit"><?=(int)$r['is_active']?'Hide':'Show'?></button></form> <form method="post" style="display:inline" onsubmit="return confirm('Delete this menu item and its child items?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn btn-outline" type="submit">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../includes/footer.php';?>